            if (was != null && same(was.claimed(), now.claimed()) && same(was.dueTotal(), now.dueTotal())) return;
            audit.record("ROLLUP" + prefix + " person=" + now.name() + " claimed=" + show(now.claimed())
                    + " due-total=" + show(now.dueTotal()));
        });
